#[test]
fn round_trip_expression_with_type_arguments() {
    let file = FileOrdinals::default();
    let data = ExpressionWithTypeArgumentsData {
        type_arguments: Ref::from_raw(17),
        expression: Ref::from_raw(24),
    };
    let record = ExpressionWithTypeArgumentsRecord::new(&file, 3, 19, 41, &data);
    assert_eq!(record.data(), data);
    assert_eq!(record.header.index(), 1);
    assert_eq!(
        (record.header.pos, record.header.end, record.header.flags),
        (3, 19, 41)
    );
    assert!(std::ptr::eq(record.tail(), &record.tail));
    let mut names = Vec::new();
    record.child_slots(
        |_| SyntaxKind::JSDocTypeExpression,
        |slot| {
            names.push(match slot {
                ChildSlot::Node(n, _) | ChildSlot::List(n, _) => n,
            })
        },
    );
    assert_eq!(names, Vec::<&str>::from(["expression", "typeArguments"]));
    let mut identity = record;
    identity.apply_child_slots(|_| SyntaxKind::JSDocTypeExpression, |slot| slot);
    assert_eq!(identity.data(), data);
    let mut lookup = Lookup::default();
    let _ = &mut lookup;
    lookup.lists.insert(
        17,
        vec![Ref::from_raw(1017).unwrap(), Ref::from_raw(2017).unwrap()],
    );
    let mut visited = Vec::new();
    record.for_each_child(&lookup, |id| {
        visited.push(id.raw());
        false
    });
    assert_eq!(visited, Vec::<u32>::from([24, 1017, 2017]));
    assert!(record.try_visit(&lookup, |_| Ok::<_, ()>(())).is_ok());
    let missing = NodeData::missing(SyntaxKind::ExpressionWithTypeArguments)
        .as_expression_with_type_arguments()
        .unwrap();
    assert_eq!(
        ExpressionWithTypeArgumentsRecord::new(&file, 0, 0, 0, &missing).data(),
        missing
    );
}
